def drop_unused_import(path, statement, symbol, label):
    """AnkiDroid는 fatal_warnings가 켜져 있어 미사용 import가 빌드를 깨뜨립니다."""
    full = os.path.join(ROOT, path)
    text = open(full, encoding="utf-8").read()
    line = statement + "\n"
    if line not in text:
        print("already applied: " + label)
        return
    body = text.replace(line, "", 1)
    if symbol in body:
        print("still used, keeping import: " + label)
        return
    open(full, "w", encoding="utf-8").write(body)
    print("removed unused import: " + label)


