# ---------------------------------------------------------------- 붙여넣기 이미지 복사
# 위 패치 뒤에 이어서 적용됩니다. 파일 이름을 못 얻는 앱에서도 되도록
# 이름 조회를 거치지 않고 내용만 복사합니다.
optional_patch('AnkiDroid/src/main/java/com/ichi2/anki/NoteEditorFragment.kt',
               '                    try {\n                        val i =\n                            Intent().apply {\n                                addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)\n                                clipData = ClipData.newUri(resolver, uri.toString(), uri)\n                            }\n                        val path = ImportUtils.getFileCachedCopy(requireContext(), i)\n                        if (path != null) {\n                            setupImageOcclusionEditor(path)\n                        } else {\n                            Timber.w("could not make a cached copy of the clipboard image")\n                            showSnackbar(TR.editingNoImageFoundOnClipboard())\n                        }\n                    } catch (e: Exception) {',
               '                    try {\n                        // ImportUtils.getFileCachedCopy 는 콘텐츠 제공자에게 파일 이름을\n                        // 먼저 묻고, 못 받으면 거기서 포기합니다. 이름을 안 알려주는 앱이\n                        // 있어서 붙여넣기만 실패했습니다. 드래그로 넣을 때는 이 경로를\n                        // 타지 않고 내용만 읽어 저장하기 때문에 잘 되던 겁니다.\n                        // 여기서도 이름에 기대지 않고 내용만 캐시에 복사합니다.\n                        val extension =\n                            android.webkit.MimeTypeMap\n                                .getSingleton()\n                                .getExtensionFromMimeType(resolver.getType(uri)) ?: "jpg"\n                        val target =\n                            File.createTempFile("occlusion_", ".$extension", requireContext().cacheDir)\n                        val copied =\n                            resolver.openInputStream(uri)?.use { input ->\n                                target.outputStream().use { output -> input.copyTo(output) }\n                                true\n                            } ?: false\n\n                        if (copied && target.length() > 0L) {\n                            setupImageOcclusionEditor(target.absolutePath)\n                        } else {\n                            target.delete()\n                            Timber.w("could not read the clipboard image")\n                            showSnackbar(TR.editingNoImageFoundOnClipboard())\n                        }\n                    } catch (e: Exception) {',
               "image occlusion paste without filename lookup")

# ---------------------------------------------------------------- 필드에 이미지 붙여넣기
# Ctrl+V 경로도 첫 항목의 URI 와 클립보드 설명의 MIME 타입만 봅니다.
# 가리기 붙여넣기와 같은 방식으로 항목을 전부 훑습니다.
optional_patch('AnkiDroid/src/main/java/com/ichi2/anki/FieldEditText.kt',
               '        if (id == android.R.id.paste) {\n            if (hasMedia(clipboard)) {\n                return onPaste(getUri(clipboard), getDescription(clipboard))\n            }\n            return pastePlainText()\n        }',
               '        if (id == android.R.id.paste) {\n            // 앱에 따라 이미지 URI 가 첫 항목이 아니거나, 클립보드 설명의 MIME 타입이\n            // 미디어로 표시되지 않습니다. 그러면 원본은 아무 일도 안 하거나 텍스트만\n            // 붙여넣습니다. 항목을 전부 훑어 실제 타입을 확인한 뒤 판단합니다.\n            firstMediaUri()?.let { return onPaste(it, getDescription(clipboard)) }\n            if (hasMedia(clipboard)) {\n                return onPaste(getUri(clipboard), getDescription(clipboard))\n            }\n            return pastePlainText()\n        }',
               "field paste media detection")

optional_patch('AnkiDroid/src/main/java/com/ichi2/anki/FieldEditText.kt',
               '    @VisibleForTesting(otherwise = VisibleForTesting.PRIVATE)\n    fun pastePlainText(): Boolean {',
               '    /**\n     * 클립보드의 모든 항목을 훑어 첫 미디어 URI 를 찾습니다.\n     *\n     * 원본은 첫 항목만 보고, 그것도 클립보드 설명에 적힌 MIME 타입만 믿습니다.\n     * 이미지를 뒤쪽 항목에 넣거나 타입을 알려주지 않는 앱에서는 붙여넣기가\n     * 아무 일도 하지 않습니다. 여기서는 실제 타입을 직접 물어봅니다.\n     */\n    private fun firstMediaUri(): Uri? {\n        val clip = clipboard?.primaryClip ?: return null\n        val resolver = context?.contentResolver ?: return null\n        for (index in 0 until clip.itemCount) {\n            val uri = clip.getItemAt(index).uri ?: continue\n            val type =\n                try {\n                    resolver.getType(uri)\n                } catch (e: Exception) {\n                    Timber.w(e, "could not read the type of a clipboard item")\n                    null\n                } ?: continue\n            if (type.startsWith("image/") || type.startsWith("audio/") || type.startsWith("video/")) {\n                return uri\n            }\n        }\n        return null\n    }\n\n    @VisibleForTesting(otherwise = VisibleForTesting.PRIVATE)\n    fun pastePlainText(): Boolean {',
               "field paste media helper",
               sentinel="private fun firstMedia")

# ---------------------------------------------------------------- 필드 붙여넣기 실제 경로
# Ctrl+V 는 FieldEditText 가 아니라 OnReceiveContentListener 로 갑니다.
# 여기도 클립보드 설명의 MIME 타입만 보고 아니면 조용히 끝냅니다.
optional_patch('AnkiDroid/src/main/java/com/ichi2/anki/NoteEditorFragment.kt',
               '            val clip = uriContent.clip\n            val description = clip.description\n\n            if (!hasMedia(description)) {\n                return@OnReceiveContentListener remaining\n            }\n\n            for (uri in clip.items().map { it.uri }) {\n                lifecycleScope.launch {\n                    try {\n                        val pasteAsPng = shouldPasteAsPng()\n                        multimediaController.onPaste(view as EditText, uri, description, pasteAsPng)\n                    } catch (e: Exception) {\n                        Timber.w(e)\n                        CrashReportService.sendExceptionReport(e, "NoteEditor::onReceiveContent")\n                    }\n                }\n            }',
               '            val clip = uriContent.clip\n            val description = clip.description\n\n            // 원본은 클립보드 설명에 적힌 MIME 타입만 믿고, 미디어가 아니라고 나오면\n            // 조용히 끝냅니다. 타입을 제대로 알려주지 않는 앱에서 붙여넣기가 아무\n            // 반응 없이 무시되던 이유입니다. 여기서는 각 URI 의 실제 타입을 물어봅니다.\n            val resolver = requireContext().contentResolver\n            val mediaItems =\n                clip\n                    .items()\n                    .mapNotNull { item ->\n                        val uri = item.uri ?: return@mapNotNull null\n                        val type =\n                            try {\n                                resolver.getType(uri)\n                            } catch (e: Exception) {\n                                Timber.w(e, "could not read the type of a pasted item")\n                                null\n                            }\n                        val isMedia =\n                            type != null &&\n                                (\n                                    type.startsWith("image/") ||\n                                        type.startsWith("audio/") ||\n                                        type.startsWith("video/")\n                                )\n                        if (hasMedia(description) || isMedia) uri to type else null\n                    }.toList()\n\n            if (mediaItems.isEmpty()) {\n                return@OnReceiveContentListener remaining\n            }\n\n            for ((uri, type) in mediaItems) {\n                // 설명이 미디어라고 말하지 않으면 실제 타입으로 만든 설명을 넘깁니다.\n                // 이 설명은 아래에서 이미지인지 영상인지 판단하는 데 쓰입니다.\n                val effectiveDescription =\n                    if (hasMedia(description) || type == null) {\n                        description\n                    } else {\n                        ClipDescription(description.label, arrayOf(type))\n                    }\n                lifecycleScope.launch {\n                    try {\n                        val pasteAsPng = shouldPasteAsPng()\n                        multimediaController.onPaste(view as EditText, uri, effectiveDescription, pasteAsPng)\n                    } catch (e: Exception) {\n                        Timber.w(e)\n                        CrashReportService.sendExceptionReport(e, "NoteEditor::onReceiveContent")\n                    }\n                }\n            }',
               "receive content media detection")

# ---------------------------------------------------------------- 붙여넣기 폴백
# 타입을 알려주지 않는 앱에서도 URI 가 있으면 이미지로 보고 시도합니다.
# 가리기 붙여넣기에서 통했던 폴백을 필드 붙여넣기에도 넣습니다.
optional_patch('AnkiDroid/src/main/java/com/ichi2/anki/FieldEditText.kt',
               '            firstMediaUri()?.let { return onPaste(it, getDescription(clipboard)) }\n            if (hasMedia(clipboard)) {\n                return onPaste(getUri(clipboard), getDescription(clipboard))\n            }\n            return pastePlainText()',
               '            firstMediaItem()?.let { (uri, description) -> return onPaste(uri, description) }\n            if (hasMedia(clipboard)) {\n                return onPaste(getUri(clipboard), getDescription(clipboard))\n            }\n            if (pastePlainText()) return true\n\n            // 여기까지 왔다는 건 클립보드에서 아무것도 못 꺼냈다는 뜻입니다.\n            // 원인을 알 수 있도록 무엇이 들어 있었는지 보여줍니다.\n            clipboard?.primaryClip?.let { clip ->\n                val types =\n                    clip.description?.let { d ->\n                        (0 until d.mimeTypeCount).joinToString(", ") { d.getMimeType(it) }\n                    } ?: "none"\n                val message = "Clipboard: $types (items: ${clip.itemCount})"\n                Timber.w("nothing pasted. %s", message)\n                com.ichi2.anki.common.utils.android.showThemedToast(context, message, false)\n            }\n            return false',
               "field paste fallback call")

optional_patch('AnkiDroid/src/main/java/com/ichi2/anki/FieldEditText.kt',
               '    /**\n     * 클립보드의 모든 항목을 훑어 첫 미디어 URI 를 찾습니다.\n     *\n     * 원본은 첫 항목만 보고, 그것도 클립보드 설명에 적힌 MIME 타입만 믿습니다.\n     * 이미지를 뒤쪽 항목에 넣거나 타입을 알려주지 않는 앱에서는 붙여넣기가\n     * 아무 일도 하지 않습니다. 여기서는 실제 타입을 직접 물어봅니다.\n     */\n    private fun firstMediaUri(): Uri? {\n        val clip = clipboard?.primaryClip ?: return null\n        val resolver = context?.contentResolver ?: return null\n        for (index in 0 until clip.itemCount) {\n            val uri = clip.getItemAt(index).uri ?: continue\n            val type =\n                try {\n                    resolver.getType(uri)\n                } catch (e: Exception) {\n                    Timber.w(e, "could not read the type of a clipboard item")\n                    null\n                } ?: continue\n            if (type.startsWith("image/") || type.startsWith("audio/") || type.startsWith("video/")) {\n                return uri\n            }\n        }\n        return null\n    }',
               '    /**\n     * 클립보드에서 붙여넣을 미디어와 그에 맞는 설명을 찾습니다.\n     *\n     * 원본은 첫 항목만 보고, 그것도 클립보드 설명에 적힌 MIME 타입만 믿습니다.\n     * 이미지를 뒤쪽 항목에 넣거나 타입을 알려주지 않는 앱에서는 붙여넣기가\n     * 아무 일도 하지 않습니다.\n     *\n     * 항목을 전부 훑어 실제 타입을 물어보고, 타입을 끝내 못 알아내더라도 URI 가\n     * 있으면 이미지로 보고 시도합니다. 가리기 붙여넣기에서 이 폴백을 넣었더니\n     * 동작했으므로, 타입을 알려주지 않는 게 원인입니다.\n     */\n    private fun firstMediaItem(): Pair<Uri, ClipDescription>? {\n        val clip = clipboard?.primaryClip ?: return null\n        val resolver = context?.contentResolver ?: return null\n        val label = clip.description?.label ?: ""\n        var fallback: Uri? = null\n\n        for (index in 0 until clip.itemCount) {\n            val uri = clip.getItemAt(index).uri ?: continue\n            if (fallback == null) {\n                fallback = uri\n            }\n            val type =\n                try {\n                    resolver.getType(uri)\n                } catch (e: Exception) {\n                    Timber.w(e, "could not read the type of a clipboard item")\n                    null\n                } ?: continue\n            if (type.startsWith("image/") || type.startsWith("audio/") || type.startsWith("video/")) {\n                return uri to ClipDescription(label, arrayOf(type))\n            }\n        }\n\n        // 타입은 못 알아냈지만 URI 는 있는 경우. 이미지로 보고 시도합니다.\n        return fallback?.let { it to ClipDescription(label, arrayOf("image/*")) }\n    }',
               "field paste fallback helper",
               sentinel="private fun firstMediaItem(")

